-- Run ONLY in the new V2 Supabase project. Never run against the GHL app database.
create extension if not exists pgcrypto;
create table if not exists public.admin_profiles (user_id uuid primary key references auth.users(id) on delete cascade, email text unique not null, created_at timestamptz not null default now());
create table if not exists public.products (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, description text not null default '', price_php numeric(12,2) not null check(price_php>=0), image_url text, published boolean not null default false, archived boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.orders (id uuid primary key default gen_random_uuid(), order_ref text unique not null, first_name text not null default '', last_name text not null default '', email text not null, phone text, checkout_type text not null default 'support', product_id uuid references public.products(id) on delete set null, product_name text, payment_method text not null check(payment_method in ('gcash','gotyme','bpi','paypal')), amount_php numeric(12,2) not null check(amount_php>0), paypal_transaction_id text, proof_path text, status text not null default 'pending_payment' check(status in ('pending_payment','under_review','paid','rejected','cancelled')), admin_notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.order_items (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id) on delete set null, product_name text not null, quantity integer not null default 1 check(quantity>0), unit_price_php numeric(12,2) not null check(unit_price_php>=0));
create table if not exists public.payment_submissions (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, payment_method text not null, proof_path text, transaction_id text, submitted_at timestamptz not null default now());
create table if not exists public.order_status_history (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, old_status text, new_status text not null, note text, changed_by text, created_at timestamptz not null default now());
create table if not exists public.email_events (id uuid primary key default gen_random_uuid(), order_id uuid references public.orders(id) on delete set null, event_type text not null, recipient text not null, provider_message_id text, outcome text not null, created_at timestamptz not null default now());
alter table public.admin_profiles enable row level security; alter table public.products enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.payment_submissions enable row level security; alter table public.order_status_history enable row level security; alter table public.email_events enable row level security;
-- No public table policies. Vercel server APIs use service-role key only server-side.
-- Create a PRIVATE Storage bucket named payment-proofs. Do not make it public.
